-- Apply to REMOTE: npx wrangler d1 execute DB --remote --file seeds/demo-users.sql
-- Remove (all of them): npx wrangler d1 execute DB --remote --file seeds/demo-users-remove.sql
--
-- These are test accounts for exercising role workspaces. Delete them when done.
-- Safe to re-run: the upsert only ever updates rows whose id starts with 'demo-'.

